style.css:
@-moz-document domain("roblox.com") {
/* Apply the custom Harry Potter image to the primary base layers */
    body, 
    .bg-vng-template,
    #container-main, 
    .wrap-container,
    .main-layout {
        background-image: url("https://gstatic.com") !important;
        background-repeat: no-repeat !important;
        background-attachment: fixed !important;
        background-position: center center !important;
        background-size: cover !important;
    }

    /* Target container blocks from your working code and make them see-through */
    .section-content, 
    .section-content-off,
    .catalog-container,
    .container-list,
    #user-account,
    .tab-horizontal-submenu.section-content {
        background-color: rgba(33, 54, 35, 0.4) !important; /* Semi-transparent background matching your palette */
        background-image: none !important;
    }

    /* Force background transparent on elements specified in your working script */
    .profile-avatar-left,
    .avatar-back,
    .place-container {
        background: transparent !important;
        background-image: none !important;
    }
}
